/* Basic reset */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}
html {
  font-size: 100%;
  scroll-behavior: smooth;
}
body {
  line-height: 1.5;
  font-family: system-ui, sans-serif;
  background: #fafafa;
  color: #222;
}
a {
  color: inherit;
  text-decoration: none;
}
img {
  max-width: 100%;
  height: auto;
}
button,
input,
select,
textarea {
  font: inherit;
}

/* Layout containers */
.site-header,
.site-footer {
  background: #111;
  color: #eee;
}
.site-header {
  padding: 1rem;
}
.site-footer {
  padding: 2rem 1rem;
  text-align: center;
  font-size: 0.875rem;
}

/* Skip link */
.skip-link {
  position: absolute;
  left: -999px;
  top: auto;
  width: 1px;
  height: 1px;
  overflow: hidden;
}
.skip-link:focus {
  left: 1rem;
  top: 1rem;
  width: auto;
  height: auto;
  background: #000;
  color: #fff;
  padding: .5rem 1rem;
  z-index: 100;
}

/* Navigation */
.primary-nav {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
  list-style: none;
}
.primary-nav li a {
  padding: .25rem 0;
}
.nav-toggle {
  display: none;
  background: transparent;
  border: none;
  color: inherit;
  font-size: 1.5rem;
  line-height: 1;
}
@media (max-width: 48em) {
  .primary-nav {
    position: absolute;
    top: 100%;
    left: 0;
    right: 0;
    background: #111;
    flex-direction: column;
    align-items: stretch;
    display: none;
  }
  .primary-nav[aria-expanded="true"] {
    display: flex;
  }
  .nav-toggle {
    display: block;
    margin-left: auto;
  }
}

/* Hero */
.hero {
  background: #eee;
  text-align: center;
  padding: 4rem 1rem;
}
.hero h1 {
  font-size: 2rem;
  margin-bottom .5rem;
}
.hero p {
  margin-bottom 1.5rem;
}
.hero .btn {
  background: #555;
  color: #fff;
  padding: .75rem 1.5rem;
  border: none;
  cursor: pointer;
}

/* Content band */
.content-band {
  padding: 2rem 1rem;
  max-width: 80rem;
  margin: 0 auto;
}
.content-band h2 {
  margin-bottom 1rem;
  font-size: 1.75rem;
}

/* Card grid */
.card-grid {
  display: grid;
  gap: 1.5rem;
  grid-template-columns: repeat(auto-fit, minmax(18rem, 1fr));
}
.card {
  background: #fff;
  border: 1px solid #ddd;
  padding: 1rem;
}
.card h3 {
  margin-bottom .5rem;
}
.card p {
  margin-bottom .75rem;
}

/* Form styles */
form {
  display: grid;
  gap: 1rem;
}
label {
  font-weight: 600;
}
input,
select,
textarea {
  width: 100%;
  padding: .5rem;
  border: 1px solid #ccc;
  border-radius: .25rem;
}
input:focus,
select:focus,
textarea:focus {
  outline: 2px solid #0066cc;
}
.button-group {
  display: flex;
  gap: .5rem;
  flex-wrap: wrap;
}
.btn {
  background: #0066cc;
  color: #fff;
  border: none;
  padding: .5rem 1rem;
  cursor: pointer;
}
.btn.secondary {
  background: #555;
}
.btn[aria-disabled="true"] {
  opacity: .5;
  cursor: not-allowed;
}

/* Modal */
.modal-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,.5);
  display: none;
  align-items: center;
  justify-content: center;
}
.modal-backdrop[aria-hidden="false"] {
  display: flex;
}
.modal {
  background: #fff;
  padding: 2rem;
  border-radius: .5rem;
  width: 90%;
  max-width: 26rem;
  position: relative;
}
.modal h2 {
  margin-top 0;
}
.modal-close {
  position: absolute;
  top: .5rem;
  right: .5rem;
  background: transparent;
  border: none;
  font-size: 1.25rem;
  line-height: 1;
}

/* Live region for toast */
[aria-live] {
  position: fixed;
  bottom: 1rem;
  left: 50%;
  transform: translateX(-50%);
  background: #000;
  color: #fff;
  padding: .75rem 1.5rem;
  border-radius: .25rem;
  opacity: 0;
  transition: opacity .3s;
}
[aria-live].show {
  opacity: .9;
}

/* Footer social placeholder */
.social-list {
  list-style: none;
  display: flex;
  gap: .75rem;
  justify-content: center;
  margin-top: 1rem;
}
.social-list li a {
  width: 2rem;
  height: 2rem;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #333;
  color: #fff;
  border-radius: .25rem;
}

/* Focus indicator */
:focus-visible {
  outline: 2px solid #0066cc;
  outline-offset: 2px;
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  * {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}
